export const PRINCIPLE_INHERITANCE_VARIATION = [
  // ============ MENDEL'S EXPERIMENTS AND TERMINOLOGY ============
  { id: 'piv-1', type: 'mcq', question: 'Gregor Johann Mendel conducted his classic hybridisation experiments primarily on which plant?', options: ['Drosophila melanogaster', 'Garden pea (Pisum sativum)', 'Mirabilis jalapa', 'Maize'], correctIndex: 1, explanation: 'Mendel conducted extensive hybridisation experiments on garden pea (Pisum sativum) between 1856 and 1863, laying the foundation of genetics.', difficulty: 'easy' },
  { id: 'piv-2', type: 'mcq', question: 'Mendel chose the garden pea for his experiments mainly because it showed several visible contrasting characters and, importantly, allowed:', options: ['Vegetative propagation only', 'Strict self-pollination as well as artificial cross-pollination', 'Only cross-pollination, with no possibility of self-pollination', 'Sterile flowers with no seed production'], correctIndex: 1, explanation: 'Pea plants normally self-pollinate but can also be artificially cross-pollinated, allowing Mendel precise control over crosses.', difficulty: 'medium' },
  { id: 'piv-3', type: 'mcq', question: 'Mendel studied seven pairs of contrasting characters in garden pea; which of the following is NOT one of them?', options: ['Seed shape (round/wrinkled)', 'Flower colour (violet/white)', 'Stem height (tall/dwarf)', 'Leaf venation (parallel/reticulate)'], correctIndex: 3, explanation: 'Leaf venation was not one of Mendel\'s seven studied traits; his traits included seed shape, seed colour, flower colour, pod shape, pod colour, stem height and flower position.', difficulty: 'medium' },
  { id: 'piv-4', type: 'mcq', question: 'In genetics, the term used to describe the alternative form of a gene, situated at a specific locus on a chromosome, is:', options: ['Genotype', 'Phenotype', 'Allele', 'Locus'], correctIndex: 2, explanation: 'An allele is an alternative form of a gene present at the same locus on homologous chromosomes.', difficulty: 'easy' },
  { id: 'piv-5', type: 'mcq', question: 'The observable trait or characteristic of an organism, resulting from the interaction between its genetic constitution and the environment, is referred to as its:', options: ['Genotype', 'Phenotype', 'Allele', 'Locus'], correctIndex: 1, explanation: 'Phenotype refers to the observable characters of an organism, while genotype refers to the genetic makeup.', difficulty: 'easy' },
  { id: 'piv-6', type: 'mcq', question: 'The genetic constitution of an organism, representing the set of genes it possesses, is called its:', options: ['Phenotype', 'Genotype', 'Karyotype', 'Ecotype'], correctIndex: 1, explanation: 'Genotype refers to the genetic makeup of an organism, distinct from phenotype, which is the observable trait.', difficulty: 'easy' },
  { id: 'piv-7', type: 'mcq', question: 'When both alleles at a locus in a diploid organism are identical, the organism is said to be:', options: ['Heterozygous for that gene', 'Homozygous for that gene', 'Hemizygous for that gene', 'Polymorphic for that gene'], correctIndex: 1, explanation: 'An organism with two identical alleles at a locus is homozygous for that gene; when the alleles differ, the organism is heterozygous.', difficulty: 'easy' },
  { id: 'piv-8', type: 'mcq', question: 'When two organisms, differing in a single pair of contrasting characters, are crossed, the cross is called a:', options: ['Dihybrid cross', 'Monohybrid cross', 'Test cross', 'Back cross'], correctIndex: 1, explanation: 'A monohybrid cross involves organisms differing in only one pair of contrasting characters (a single gene).', difficulty: 'easy' },
  { id: 'piv-9', type: 'mcq', question: 'The parental generation in a genetic cross is conventionally denoted by which symbol?', options: ['F1', 'F2', 'P', 'M'], correctIndex: 2, explanation: 'The parental generation is denoted by "P", while their offspring form the first filial generation (F1), and so on.', difficulty: 'easy' },
  { id: 'piv-10', type: 'mcq', question: 'The first filial generation, obtained by crossing two parents differing in one or more traits, is denoted by:', options: ['P', 'F1', 'F2', 'Fn'], correctIndex: 1, explanation: 'The first-generation progeny from a cross between two parents is denoted F1 (first filial generation).', difficulty: 'easy' },
  { id: 'piv-11', type: 'mcq', question: 'When Mendel crossed true-breeding tall pea plants with true-breeding dwarf pea plants, all the F1 plants were:', options: ['Tall', 'Dwarf', 'Of intermediate height', 'Half tall and half dwarf'], correctIndex: 0, explanation: 'In Mendel\'s cross of tall and dwarf pea plants, all F1 plants were tall, showing that the tall trait was dominant.', difficulty: 'easy' },
  { id: 'piv-12', type: 'mcq', question: 'The character that expresses itself in the F1 generation, masking the presence of the other allele, is called the:', options: ['Recessive character', 'Dominant character', 'Co-dominant character', 'Intermediate character'], correctIndex: 1, explanation: 'The dominant character is the one that is expressed in the F1 generation (heterozygous condition), masking the recessive character.', difficulty: 'easy' },
  { id: 'piv-13', type: 'mcq', question: 'A character that remains hidden or masked in the F1 generation but reappears in the F2 generation is called the:', options: ['Dominant character', 'Recessive character', 'Co-dominant character', 'Epistatic character'], correctIndex: 1, explanation: 'The recessive character remains suppressed in F1 but reappears in a fraction of the F2 progeny.', difficulty: 'easy' },
  { id: 'piv-14', type: 'mcq', question: 'When Mendel self-pollinated the F1 tall pea plants (from a tall x dwarf cross), the resulting F2 generation showed a phenotypic ratio of approximately:', options: ['1 tall : 1 dwarf', '1 tall : 2 dwarf', '3 tall : 1 dwarf', '9 tall : 7 dwarf'], correctIndex: 2, explanation: 'Self-pollination of F1 tall plants resulted in an F2 generation with a phenotypic ratio of approximately 3 tall : 1 dwarf.', difficulty: 'easy' },
  { id: 'piv-15', type: 'mcq', question: 'The genotypic ratio observed in the F2 generation of a typical Mendelian monohybrid cross is approximately:', options: ['1 : 2 : 1', '3 : 1', '9 : 3 : 3 : 1', '1 : 1'], correctIndex: 0, explanation: 'In a monohybrid cross, the F2 genotypic ratio is 1 homozygous dominant : 2 heterozygous : 1 homozygous recessive.', difficulty: 'medium' },
  { id: 'piv-16', type: 'assertion', question: 'Assertion (A): Mendel is regarded as the father of genetics.\nReason (R): Mendel was the first to formulate the fundamental principles of inheritance based on carefully designed, statistically analysed breeding experiments using garden pea.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'Mendel\'s methodical, statistically rigorous experiments correctly explain why he is credited as the founder of the science of genetics.', difficulty: 'medium' },
  { id: 'piv-17', type: 'assertion', question: 'Assertion (A): Mendel chose to work with garden pea rather than many other available plants.\nReason (R): Garden pea showed several easily distinguishable contrasting characters and could be manipulated for both self-pollination and cross-pollination as needed.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The convenience of visible contrasting characters and controllable pollination correctly explains why Mendel selected garden pea as his experimental organism.', difficulty: 'medium' },
  { id: 'piv-18', type: 'count', question: 'Consider the following statements about Mendel\'s work:\n1. Mendel worked on garden pea (Pisum sativum).\n2. Mendel studied seven contrasting character pairs.\n3. In Mendel\'s monohybrid cross, the F1 generation showed a blend of both parental traits.\n4. The F2 generation of a monohybrid cross shows an approximate 3:1 phenotypic ratio.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 4 are correct. Statement 3 is wrong — the F1 generation showed the dominant trait fully, not a blend of both parental traits.', difficulty: 'medium' },
  { id: 'piv-19', type: 'count', question: 'Consider the following terms and their definitions:\n1. Genotype — the genetic constitution of an organism.\n2. Phenotype — the observable characteristics of an organism.\n3. Homozygous — having two different alleles at a locus.\n4. Allele — an alternative form of a gene at a specific locus.\nHow many of the above are correctly defined?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 4 are correctly defined. Statement 3 is wrong — homozygous means having two identical (not different) alleles; having different alleles is heterozygous.', difficulty: 'medium' },
  { id: 'piv-20', type: 'matching', question: 'Match Column I (term) with Column II (definition):\nColumn I: A. Genotype  B. Phenotype  C. Homozygous  D. Heterozygous\nColumn II: i. Observable trait  ii. Two identical alleles  iii. Genetic constitution  iv. Two different alleles', options: ['A-iii, B-i, C-ii, D-iv', 'A-i, B-iii, C-iv, D-ii', 'A-iii, B-ii, C-i, D-iv', 'A-ii, B-i, C-iii, D-iv'], correctIndex: 0, explanation: 'Genotype — genetic constitution; Phenotype — observable trait; Homozygous — identical alleles; Heterozygous — different alleles.', difficulty: 'medium' },

  // ============ LAW OF DOMINANCE AND LAW OF SEGREGATION ============
  { id: 'piv-21', type: 'mcq', question: 'Mendel\'s Law of Dominance states that:', options: ['Characters are controlled by units or factors (genes), occurring in pairs, one of which dominates the other', 'Two genes always segregate together', 'All traits show intermediate expression in the F1 generation', 'Genes located on different chromosomes assort independently'], correctIndex: 0, explanation: 'The Law of Dominance states that characters are controlled by discrete units (factors/genes) present in pairs, and one factor (allele) of the pair dominates the other (recessive) in the heterozygous state.', difficulty: 'medium' },
  { id: 'piv-22', type: 'mcq', question: 'According to the Law of Dominance, in a heterozygous individual, the recessive allele:', options: ['Is expressed equally with the dominant allele', 'Fails to express itself in the presence of the dominant allele', 'Is destroyed permanently', 'Mutates into the dominant allele'], correctIndex: 1, explanation: 'The recessive allele does not express itself in the phenotype of a heterozygote, being masked by the dominant allele.', difficulty: 'medium' },
  { id: 'piv-23', type: 'mcq', question: 'Mendel\'s Law of Segregation, sometimes called the "Law of Purity of Gametes", states that:', options: ['The two alleles of a gene pair separate during gamete formation, and each gamete receives only one allele', 'Genes on different chromosomes always segregate together', 'Alleles blend permanently in the F1 generation', 'Dominant alleles are always eliminated from a population'], correctIndex: 0, explanation: 'The Law of Segregation states that the two alleles for a gene segregate (separate) during gamete formation, so that each gamete carries only one allele — remaining "pure" for that gene.', difficulty: 'medium' },
  { id: 'piv-24', type: 'mcq', question: 'The Law of Segregation applies to the behaviour of a single gene pair and holds true, as Mendel observed, for:', options: ['A specific number of genes only, but not all', 'All the seven characters he studied', 'Only dominant traits, not recessive ones', 'Only characters affecting flower colour'], correctIndex: 1, explanation: 'Mendel found that the Law of Segregation held true for all seven pairs of contrasting characters he studied, and is now considered a general principle of inheritance.', difficulty: 'medium' },
  { id: 'piv-25', type: 'mcq', question: 'The reappearance of the recessive character in a fraction (about 1/4th) of the F2 generation, despite its absence in F1, is best explained by:', options: ['The alleles blending irreversibly in F1 and never separating again', 'The alleles remaining discrete, unblended units that segregate independently during gamete formation', 'A completely new mutation arising in F2', 'Environmental influence alone, without any genetic basis'], correctIndex: 1, explanation: 'The reappearance of the recessive trait in F2 is explained by the segregation of the discrete, unblended dominant and recessive alleles during gamete formation in the F1 heterozygote.', difficulty: 'medium' },
  { id: 'piv-26', type: 'assertion', question: 'Assertion (A): In a monohybrid cross, the F1 generation shows only the dominant phenotype, yet both parental alleles are retained.\nReason (R): The Law of Dominance ensures that the dominant allele masks the recessive one in the phenotype, but the Law of Segregation ensures that both alleles remain intact in the genotype and separate during gamete formation.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The combined action of the Law of Dominance (phenotypic masking) and Law of Segregation (genotypic retention/separation) correctly explains the observed pattern in the assertion.', difficulty: 'hard' },
  { id: 'piv-27', type: 'assertion', question: 'Assertion (A): The Law of Segregation is often called the "Law of Purity of Gametes".\nReason (R): During gamete formation, the two alleles of a gene pair separate such that each gamete receives only one allele, remaining unmixed (pure) for that particular gene.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The separation of alleles into individual, unmixed gametes correctly explains why the Law of Segregation is also referred to as the Law of Purity of Gametes.', difficulty: 'medium' },
  { id: 'piv-28', type: 'count', question: 'Consider the following statements about Mendel\'s laws:\n1. The Law of Dominance explains why F1 hybrids show only one of the two parental traits.\n2. The Law of Segregation explains the reappearance of the recessive trait in F2.\n3. The Law of Segregation states that alleles blend together permanently and never separate.\n4. The Law of Dominance applies specifically to the interaction between two alleles of the same gene.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 4 are correct. Statement 3 is wrong — the Law of Segregation states that alleles remain discrete and do separate during gamete formation, they do not blend permanently.', difficulty: 'medium' },
  { id: 'piv-29', type: 'statement', question: 'Statement I: According to the Law of Segregation, each gamete carries only one allele for a given gene.\nStatement II: This segregation of alleles occurs during meiosis, specifically as homologous chromosomes separate.\nIn light of the above statements, choose the most appropriate answer:', options: ['Both Statement I and Statement II are correct, and Statement II correctly explains the mechanism behind Statement I', 'Both statements are correct, but Statement II is unrelated to Statement I', 'Statement I is correct, Statement II is incorrect', 'Statement I is incorrect, Statement II is correct'], correctIndex: 0, explanation: 'The segregation of alleles (Statement I) is mechanistically explained by the separation of homologous chromosomes during meiosis (Statement II).', difficulty: 'medium' },
  { id: 'piv-30', type: 'mcq', question: 'A cross between an F1 heterozygous individual and one of the homozygous parents is called a:', options: ['Back cross', 'Dihybrid cross', 'Reciprocal cross', 'Monohybrid cross'], correctIndex: 0, explanation: 'A back cross is a cross between the F1 hybrid and either of its parents (homozygous dominant or recessive).', difficulty: 'medium' },
  { id: 'piv-31', type: 'mcq', question: 'A specific type of back cross, used to determine whether an individual showing a dominant phenotype is homozygous or heterozygous for that gene, is called a:', options: ['Test cross', 'Dihybrid cross', 'Reciprocal cross', 'Trihybrid cross'], correctIndex: 0, explanation: 'A test cross involves crossing an individual of unknown genotype (showing the dominant phenotype) with a homozygous recessive individual, to determine the unknown genotype.', difficulty: 'medium' },
  { id: 'piv-32', type: 'mcq', question: 'In a test cross, if the unknown individual is heterozygous (Tt) for the trait, crossing it with a homozygous recessive (tt) individual would produce offspring in what approximate phenotypic ratio?', options: ['All dominant phenotype', '1 dominant : 1 recessive', '3 dominant : 1 recessive', 'All recessive phenotype'], correctIndex: 1, explanation: 'A heterozygous individual (Tt) crossed with a homozygous recessive (tt) produces offspring in a 1:1 ratio of dominant to recessive phenotypes.', difficulty: 'medium' },
  { id: 'piv-33', type: 'mcq', question: 'In a test cross, if the unknown individual is actually homozygous dominant (TT) for the trait, crossing it with a homozygous recessive (tt) individual would produce offspring that are:', options: ['All showing the dominant phenotype', 'All showing the recessive phenotype', 'A 3:1 ratio of dominant to recessive', 'A 9:3:3:1 ratio'], correctIndex: 0, explanation: 'A homozygous dominant individual (TT) crossed with tt produces all Tt offspring, which show only the dominant phenotype.', difficulty: 'medium' },
  { id: 'piv-34', type: 'assertion', question: 'Assertion (A): A test cross is a useful tool to determine the genotype of an individual showing a dominant phenotype.\nReason (R): Crossing the individual with a homozygous recessive parent reveals, through the ratio of offspring phenotypes, whether the individual is homozygous or heterozygous for the gene in question.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The distinct offspring ratios produced (all dominant vs. 1:1) correctly explain why a test cross can reveal the unknown genotype, as stated in the assertion.', difficulty: 'medium' },

  // ============ LAW OF INDEPENDENT ASSORTMENT, DIHYBRID CROSS ============
  { id: 'piv-35', type: 'mcq', question: 'A cross between two individuals differing in two pairs of contrasting characters simultaneously is called a:', options: ['Monohybrid cross', 'Dihybrid cross', 'Test cross', 'Back cross'], correctIndex: 1, explanation: 'A dihybrid cross studies the inheritance of two genes/traits simultaneously.', difficulty: 'easy' },
  { id: 'piv-36', type: 'mcq', question: 'In Mendel\'s classic dihybrid cross involving seed shape (round/wrinkled) and seed colour (yellow/green), the F1 generation, obtained by crossing round-yellow and wrinkled-green true-breeding parents, showed:', options: ['All round-yellow seeds', 'All round-green seeds', 'A mixture of all four combinations', 'All wrinkled-green seeds'], correctIndex: 0, explanation: 'The F1 generation of this cross was uniformly round and yellow, indicating that round shape and yellow colour were dominant traits.', difficulty: 'medium' },
  { id: 'piv-37', type: 'mcq', question: 'When Mendel self-pollinated the F1 (round-yellow) plants from his dihybrid cross, the F2 generation showed how many distinct phenotypic classes?', options: ['Two', 'Three', 'Four', 'Six'], correctIndex: 2, explanation: 'The F2 generation showed four phenotypic classes: round-yellow, round-green, wrinkled-yellow and wrinkled-green.', difficulty: 'medium' },
  { id: 'piv-38', type: 'mcq', question: 'The classic phenotypic ratio observed in the F2 generation of a dihybrid cross, involving two independently assorting genes, is approximately:', options: ['3 : 1', '1 : 2 : 1', '9 : 3 : 3 : 1', '1 : 1 : 1 : 1'], correctIndex: 2, explanation: 'The classic dihybrid F2 phenotypic ratio is 9:3:3:1, reflecting the independent assortment of two gene pairs.', difficulty: 'medium' },
  { id: 'piv-39', type: 'mcq', question: 'In Mendel\'s dihybrid cross F2 generation, the appearance of two new combinations of traits not seen in either parent (e.g., round-green and wrinkled-yellow) provided evidence for:', options: ['Complete linkage between the two genes', 'Independent assortment of the two genes during gamete formation', 'Co-dominance between the two genes', 'A single gene controlling both traits'], correctIndex: 1, explanation: 'The appearance of new (recombinant) phenotypic combinations, not present in the parental generation, provided key evidence that the two genes assort independently.', difficulty: 'medium' },
  { id: 'piv-40', type: 'mcq', question: 'Mendel\'s Law of Independent Assortment states that:', options: ['When two pairs of traits are combined in a hybrid, segregation of one pair of characters is independent of the other pair', 'Two genes always segregate together into the same gamete', 'Dominant alleles are always inherited together', 'Only one gene can be inherited at a time'], correctIndex: 0, explanation: 'The Law of Independent Assortment states that when two pairs of traits are combined in a hybrid, segregation of one pair of characters is independent of the other pair.', difficulty: 'medium' },
  { id: 'piv-41', type: 'mcq', question: 'The Law of Independent Assortment, as later understood through chromosome theory, applies specifically to genes that are:', options: ['Located on the same chromosome, very close together', 'Located on different chromosomes, or far apart on the same chromosome', 'Always located on the X chromosome', 'Never inherited in the same individual'], correctIndex: 1, explanation: 'Independent assortment holds true for genes located on different chromosomes or genes far apart on the same chromosome, where recombination frequency is high.', difficulty: 'hard' },
  { id: 'piv-42', type: 'mcq', question: 'In a typical 9:3:3:1 dihybrid F2 ratio, the class representing "9" corresponds to individuals showing:', options: ['Both recessive traits', 'Both dominant traits', 'One dominant and one recessive trait (specific combination A)', 'One dominant and one recessive trait (specific combination B)'], correctIndex: 1, explanation: 'In the 9:3:3:1 ratio, the "9" class represents individuals showing both dominant phenotypes.', difficulty: 'medium' },
  { id: 'piv-43', type: 'mcq', question: 'In a typical 9:3:3:1 dihybrid F2 ratio, the class representing "1" corresponds to individuals showing:', options: ['Both dominant traits', 'Both recessive traits', 'A mixture of dominant and recessive traits', 'Sterile offspring'], correctIndex: 1, explanation: 'The smallest class in the 9:3:3:1 ratio, representing "1", corresponds to individuals homozygous recessive for both traits.', difficulty: 'medium' },
  { id: 'piv-44', type: 'assertion', question: 'Assertion (A): The 9:3:3:1 phenotypic ratio observed in dihybrid crosses provided strong evidence for the Law of Independent Assortment.\nReason (R): This ratio can only be explained if the two gene pairs segregate independently of each other during gamete formation, generating four types of gametes in equal proportion.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The generation of four equally likely gamete types through independent segregation correctly explains the characteristic 9:3:3:1 dihybrid ratio.', difficulty: 'hard' },
  { id: 'piv-45', type: 'assertion', question: 'Assertion (A): The Law of Independent Assortment does not hold true for all pairs of genes in an organism.\nReason (R): Genes located very close together on the same chromosome tend to be inherited together (linked) rather than assorting independently.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The phenomenon of gene linkage on the same chromosome correctly explains why independent assortment is not universal for all gene pairs.', difficulty: 'medium' },
  { id: 'piv-46', type: 'count', question: 'Consider the following statements about the dihybrid cross:\n1. Mendel\'s classic dihybrid cross involved seed shape and seed colour.\n2. The F1 generation of a dihybrid cross shows a blend of all parental traits.\n3. The F2 generation of a dihybrid cross typically shows four distinct phenotypic classes.\n4. The classic F2 dihybrid ratio is 9:3:3:1.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 3 and 4 are correct. Statement 2 is wrong — F1 shows the dominant phenotypes fully, not a blend.', difficulty: 'medium' },
  { id: 'piv-47', type: 'count', question: 'Consider the following statements about independent assortment:\n1. It applies universally to all gene pairs, regardless of their chromosomal location.\n2. It results in new (recombinant) combinations of traits in the offspring.\n3. It was inferred from the 9:3:3:1 phenotypic ratio observed in dihybrid crosses.\n4. It only applies to genes located on the same chromosome, close together.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 1, explanation: 'Statements 2 and 3 are correct. Statement 1 is wrong (it does not apply universally — linked genes are an exception), and statement 4 is wrong (independent assortment applies to genes on different chromosomes or far apart on the same one, not genes close together).', difficulty: 'hard' },
  { id: 'piv-48', type: 'matching', question: 'Match Column I (Mendelian law) with Column II (key description):\nColumn I: A. Law of Dominance  B. Law of Segregation  C. Law of Independent Assortment\nColumn II: i. Alleles of different genes segregate independently of each other  ii. One allele masks the other in a heterozygote  iii. Alleles of a gene pair separate during gamete formation', options: ['A-ii, B-iii, C-i', 'A-i, B-ii, C-iii', 'A-iii, B-i, C-ii', 'A-ii, B-i, C-iii'], correctIndex: 0, explanation: 'Law of Dominance — one allele masks the other; Law of Segregation — alleles separate during gamete formation; Law of Independent Assortment — different gene pairs segregate independently.', difficulty: 'medium' },

  // ============ INCOMPLETE DOMINANCE, CO-DOMINANCE, MULTIPLE ALLELES, PLEIOTROPY ============
  { id: 'piv-49', type: 'mcq', question: 'In Mirabilis jalapa (four o\' clock plant), when a red-flowered plant is crossed with a white-flowered plant, the F1 progeny shows:', options: ['All red flowers', 'All white flowers', 'Pink flowers, an intermediate phenotype', 'A mixture of red and white flowers on the same plant'], correctIndex: 2, explanation: 'In Mirabilis jalapa, the F1 progeny of a red x white cross shows pink flowers, an intermediate phenotype, illustrating incomplete dominance.', difficulty: 'easy' },
  { id: 'piv-50', type: 'mcq', question: 'The phenomenon in which neither allele of a gene pair is completely dominant over the other, resulting in an intermediate phenotype in the heterozygote, is called:', options: ['Codominance', 'Incomplete dominance', 'Multiple allelism', 'Pleiotropy'], correctIndex: 1, explanation: 'Incomplete dominance occurs when the heterozygote shows a phenotype intermediate between the two homozygous parental phenotypes.', difficulty: 'easy' },
  { id: 'piv-51', type: 'mcq', question: 'When the pink-flowered F1 plants of Mirabilis jalapa are self-pollinated, the F2 generation shows a phenotypic ratio of:', options: ['3 red : 1 white', '1 red : 2 pink : 1 white', '9 red : 3 pink : 4 white', '1 red : 1 white'], correctIndex: 1, explanation: 'Self-pollinating the pink F1 plants gives an F2 ratio of 1 red : 2 pink : 1 white, matching the underlying genotypic ratio, since phenotype and genotype ratios coincide in incomplete dominance.', difficulty: 'medium' },
  { id: 'piv-52', type: 'mcq', question: 'The phenomenon in which both alleles of a gene pair express themselves fully and independently in the heterozygote, without either being masked, is called:', options: ['Incomplete dominance', 'Codominance', 'Recessiveness', 'Epistasis'], correctIndex: 1, explanation: 'Codominance occurs when both alleles present in a heterozygote are individually and fully expressed, as in the ABO blood group system.', difficulty: 'easy' },
  { id: 'piv-53', type: 'mcq', question: 'A classic example of codominance in humans is illustrated by which blood group system?', options: ['Rh blood group system', 'ABO blood group system', 'MN blood group system alone, without codominance', 'None of the human blood group systems show codominance'], correctIndex: 1, explanation: 'The ABO blood group system illustrates codominance, since individuals with genotype IAIB express both A and B antigens simultaneously.', difficulty: 'easy' },
  { id: 'piv-54', type: 'mcq', question: 'The ABO blood group system in humans is controlled by a single gene locus, "I", which exists in how many allelic forms?', options: ['Two', 'Three (IA, IB, i)', 'Four', 'Five'], correctIndex: 1, explanation: 'The ABO blood group gene "I" has three allelic forms: IA, IB, and i, making it a classic example of multiple alleles.', difficulty: 'medium' },
  { id: 'piv-55', type: 'mcq', question: 'In the ABO blood group system, the allele "i" is recessive to both IA and IB, while IA and IB show which relationship with each other?', options: ['IA is dominant over IB', 'IB is dominant over IA', 'IA and IB are codominant', 'Both IA and IB are recessive to i'], correctIndex: 2, explanation: 'IA and IB are codominant to each other; both alleles are recessive-dominant compared to i, but they are codominant to one another.', difficulty: 'medium' },
  { id: 'piv-56', type: 'mcq', question: 'A person with blood group AB has the genotype:', options: ['IAIA', 'IBIB', 'IAIB', 'ii'], correctIndex: 2, explanation: 'Blood group AB arises from the genotype IAIB, where both A and B antigens are expressed due to codominance.', difficulty: 'medium' },
  { id: 'piv-57', type: 'mcq', question: 'A person with blood group O has the genotype:', options: ['IAi', 'IBi', 'IAIB', 'ii'], correctIndex: 3, explanation: 'Blood group O results from the homozygous recessive genotype ii, since the i allele does not produce either antigen.', difficulty: 'medium' },
  { id: 'piv-58', type: 'mcq', question: 'The presence of three or more alternative forms of a gene within a population, though any individual diploid organism can carry only two of them, is called:', options: ['Codominance', 'Incomplete dominance', 'Multiple alleles', 'Epistasis'], correctIndex: 2, explanation: 'Multiple alleles refers to a gene having more than two allelic forms present in a population, even though an individual can carry at most two.', difficulty: 'medium' },
  { id: 'piv-59', type: 'mcq', question: 'The condition in which a single gene exerts simultaneous effects on multiple, seemingly unrelated phenotypic characteristics is called:', options: ['Pleiotropy', 'Polygenic inheritance', 'Codominance', 'Incomplete dominance'], correctIndex: 0, explanation: 'Pleiotropy occurs when a single gene influences multiple, apparently unrelated phenotypic traits.', difficulty: 'medium' },
  { id: 'piv-60', type: 'mcq', question: 'Phenylketonuria (PKU) in humans, caused by a single gene mutation, is often cited as an example of:', options: ['Incomplete dominance', 'Pleiotropy, since the gene affects multiple aspects of the phenotype', 'Codominance', 'Multiple alleles, unrelated to pleiotropy'], correctIndex: 1, explanation: 'Phenylketonuria is a classic example of pleiotropy, as the mutant gene affects several traits simultaneously, contributing to a multi-symptom phenotype.', difficulty: 'medium' },
  { id: 'piv-61', type: 'assertion', question: 'Assertion (A): In the ABO blood group system, the phenotype and genotype ratios in a cross may sometimes coincide with those seen in incomplete dominance for certain crosses.\nReason (R): This is because both incomplete dominance and codominance can, under specific parental combinations, produce distinguishable heterozygous phenotypes rather than the heterozygote resembling one homozygous parent.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'Since both mechanisms yield a distinguishable heterozygous phenotype (rather than masking), the coincidence of genotype and phenotype ratios in certain crosses is correctly explained by R.', difficulty: 'hard' },
  { id: 'piv-62', type: 'assertion', question: 'Assertion (A): Multiple allelism and pleiotropy are distinct genetic phenomena.\nReason (R): Multiple allelism refers to the existence of more than two alleles of a single gene within a population, whereas pleiotropy refers to a single gene affecting multiple phenotypic traits.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The clear conceptual difference described in R (allele number vs. trait number) correctly explains why multiple allelism and pleiotropy are considered distinct phenomena.', difficulty: 'medium' },
  { id: 'piv-63', type: 'count', question: 'Consider the following statements about incomplete dominance and codominance:\n1. Incomplete dominance results in an intermediate phenotype in the heterozygote.\n2. Codominance results in both alleles being fully and independently expressed in the heterozygote.\n3. The ABO blood group system is an example of incomplete dominance.\n4. Mirabilis jalapa flower colour is an example of codominance.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 1, explanation: 'Statements 1 and 2 are correct. Statement 3 is wrong (ABO blood group demonstrates codominance, not incomplete dominance), and statement 4 is wrong (Mirabilis jalapa demonstrates incomplete dominance, not codominance).', difficulty: 'medium' },
  { id: 'piv-64', type: 'count', question: 'Consider the following ABO blood group genotypes:\n1. IAIA\n2. IAi\n3. IBIB\n4. IAIB\n5. ii\nHow many of the above genotypes result in blood group A phenotype?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 1, explanation: 'IAIA and IAi both result in blood group A phenotype (since IA is dominant over i). IBIB gives group B, IAIB gives group AB, and ii gives group O.', difficulty: 'medium' },
  { id: 'piv-65', type: 'statement', question: 'Statement I: In incomplete dominance, the F2 phenotypic ratio (1:2:1) matches the underlying genotypic ratio.\nStatement II: This occurs because each genotype (homozygous dominant, heterozygous, homozygous recessive) produces a visibly distinct phenotype.\nIn light of the above statements, choose the most appropriate answer:', options: ['Both Statement I and Statement II are correct, and Statement II correctly explains Statement I', 'Both statements are correct, but Statement II does not explain Statement I', 'Statement I is correct, Statement II is incorrect', 'Statement I is incorrect, Statement II is correct'], correctIndex: 0, explanation: 'Since each genotype yields a distinct phenotype under incomplete dominance, the phenotypic and genotypic ratios necessarily coincide, correctly linking Statement II to Statement I.', difficulty: 'medium' },
  { id: 'piv-66', type: 'matching', question: 'Match Column I (genetic phenomenon) with Column II (example):\nColumn I: A. Incomplete dominance  B. Codominance  C. Multiple alleles  D. Pleiotropy\nColumn II: i. Phenylketonuria  ii. ABO blood group system (3 alleles)  iii. Flower colour in Mirabilis jalapa  iv. Antigen expression in AB blood group', options: ['A-iii, B-iv, C-ii, D-i', 'A-i, B-ii, C-iii, D-iv', 'A-iii, B-ii, C-iv, D-i', 'A-iv, B-iii, C-i, D-ii'], correctIndex: 0, explanation: 'Incomplete dominance — Mirabilis jalapa; Codominance — AB blood group antigen expression; Multiple alleles — ABO system; Pleiotropy — Phenylketonuria.', difficulty: 'hard' },

  // ============ CHROMOSOMAL THEORY, LINKAGE AND RECOMBINATION ============
  { id: 'piv-67', type: 'mcq', question: 'The chromosomal theory of inheritance, proposing that chromosomes are the carriers of genetic material, was independently proposed by:', options: ['Mendel and Darwin', 'Sutton and Boveri', 'Morgan and Watson', 'Fleming and Crick'], correctIndex: 1, explanation: 'Walter Sutton and Theodor Boveri independently proposed the chromosomal theory of inheritance, noting the parallel behaviour of chromosomes and Mendelian factors.', difficulty: 'medium' },
  { id: 'piv-68', type: 'mcq', question: 'The chromosomal theory of inheritance was strongly supported by experimental work using which organism, carried out by Thomas Hunt Morgan and colleagues?', options: ['Garden pea', 'Drosophila melanogaster (fruit fly)', 'Maize', 'Mice'], correctIndex: 1, explanation: 'Morgan and his colleagues used Drosophila melanogaster to experimentally validate the chromosomal theory of inheritance and to study linkage and crossing over.', difficulty: 'easy' },
  { id: 'piv-69', type: 'mcq', question: 'Morgan chose Drosophila melanogaster for genetic studies mainly due to which of the following advantages?', options: ['Extremely long generation time and requiring elaborate laboratory maintenance', 'Very short life cycle, producing several generations within a year, easy to maintain in the laboratory', 'Sexual reproduction being entirely absent', 'A very large body size, making manipulations easier'], correctIndex: 1, explanation: 'Drosophila offered practical advantages such as a short life cycle, ease of maintenance in the lab, and the production of many generations within a short time.', difficulty: 'medium' },
  { id: 'piv-70', type: 'mcq', question: 'The tendency of two or more genes located on the same chromosome to be inherited together, rather than assorting independently, is called:', options: ['Recombination', 'Linkage', 'Segregation', 'Codominance'], correctIndex: 1, explanation: 'Linkage refers to the physical association of genes on the same chromosome, causing them to be inherited together more often than expected by independent assortment.', difficulty: 'medium' },
  { id: 'piv-71', type: 'mcq', question: 'The generation of new combinations of alleles, different from those found in either parent, through the process of crossing over during meiosis, is called:', options: ['Linkage', 'Recombination', 'Mutation', 'Independent assortment failure'], correctIndex: 1, explanation: 'Recombination is the process that generates new allele combinations, largely due to crossing over between homologous chromosomes during meiosis.', difficulty: 'medium' },
  { id: 'piv-72', type: 'mcq', question: 'Morgan observed that when the genes for body colour and wing size in Drosophila were closely located on the same chromosome, the proportion of recombinant progeny was:', options: ['Very high, close to what independent assortment would predict', 'Very low, showing tight (strong) linkage', 'Exactly 50%, in all cases', 'Zero, no recombinants at all'], correctIndex: 1, explanation: 'When genes are close together on the same chromosome, they show tight linkage and a very low frequency of recombinant offspring.', difficulty: 'medium' },
  { id: 'piv-73', type: 'mcq', question: 'When two genes are located far apart on the same chromosome, they tend to show:', options: ['Very strong linkage, with almost no recombinants', 'Higher recombination frequency, since there is more chance for crossing over between them', 'Complete absence of segregation', 'No possibility of recombination at all'], correctIndex: 1, explanation: 'Genes located far apart on the same chromosome show a higher percentage of recombination, since there is a greater physical distance over which crossing over can occur.', difficulty: 'medium' },
  { id: 'piv-74', type: 'assertion', question: 'Assertion (A): The frequency of recombination between two linked genes can be used to estimate the relative distance between them on a chromosome.\nReason (R): The likelihood of a crossover event occurring between two genes generally increases with the physical distance separating them on the chromosome.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The direct relationship between physical distance and crossover frequency correctly explains why recombination frequency can be used to estimate gene distances (as used in genetic mapping).', difficulty: 'hard' },
  { id: 'piv-75', type: 'assertion', question: 'Assertion (A): Not all pairs of genes obey Mendel\'s Law of Independent Assortment.\nReason (R): Genes located on the same chromosome, especially those situated close together, tend to be inherited together due to linkage, deviating from independent assortment.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The phenomenon of linkage between physically close genes correctly explains why independent assortment does not apply universally.', difficulty: 'medium' },
  { id: 'piv-76', type: 'count', question: 'Consider the following statements about linkage and recombination:\n1. Genes located close together on the same chromosome show low recombination frequency.\n2. Genes located far apart on the same chromosome show high recombination frequency.\n3. Linkage was experimentally demonstrated by Morgan using Drosophila.\n4. The chromosomal theory of inheritance was proposed by Watson and Crick.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 3 are correct. Statement 4 is wrong — the chromosomal theory of inheritance was proposed by Sutton and Boveri, not Watson and Crick.', difficulty: 'medium' },
  { id: 'piv-77', type: 'statement', question: 'Statement I: Linkage and recombination are complementary phenomena observed among genes located on the same chromosome.\nStatement II: Complete linkage, where no recombination ever occurs between two genes, is the most commonly observed pattern in nature.\nIn light of the above statements, choose the most appropriate answer:', options: ['Both Statement I and Statement II are correct', 'Both Statement I and Statement II are incorrect', 'Statement I is correct but Statement II is incorrect', 'Statement I is incorrect but Statement II is correct'], correctIndex: 2, explanation: 'Statement I is correct. Statement II is incorrect — complete linkage (zero recombination) is relatively rare; most linked genes show some degree of recombination, varying with distance.', difficulty: 'medium' },

  // ============ SEX DETERMINATION ============
  { id: 'piv-78', type: 'mcq', question: 'The mechanism by which the sex of an individual is genetically determined is called:', options: ['Sex determination', 'Sex linkage', 'Sex differentiation only, unrelated to genetics', 'Autosomal inheritance'], correctIndex: 0, explanation: 'Sex determination refers to the genetic (chromosomal) mechanisms that determine whether an individual develops as male or female.', difficulty: 'easy' },
  { id: 'piv-79', type: 'mcq', question: 'In humans, the sex chromosome constitution of a typical male is:', options: ['XX', 'XY', 'XO', 'ZW'], correctIndex: 1, explanation: 'In humans, males have an XY sex chromosome constitution, while females have XX.', difficulty: 'easy' },
  { id: 'piv-80', type: 'mcq', question: 'In humans, the sex chromosome constitution of a typical female is:', options: ['XY', 'XX', 'ZZ', 'ZW'], correctIndex: 1, explanation: 'In humans, females have an XX sex chromosome constitution, while males have XY.', difficulty: 'easy' },
  { id: 'piv-81', type: 'mcq', question: 'In humans, the sex of a child is determined by the type of sex chromosome carried by which parent\'s gamete?', options: ['The mother, since the egg determines sex', 'The father, since the sperm can carry either an X or a Y chromosome', 'Neither parent; sex is determined randomly after fertilisation', 'Both parents equally and simultaneously in every case'], correctIndex: 1, explanation: 'Since the mother always contributes an X chromosome, the sex of the offspring in humans depends on whether the father\'s sperm carries an X or a Y chromosome.', difficulty: 'medium' },
  { id: 'piv-82', type: 'mcq', question: 'This human sex determination pattern (XX in females, XY in males) is generally referred to as the:', options: ['XY type of sex determination', 'ZW type of sex determination', 'XO type of sex determination', 'Haplodiploid sex determination'], correctIndex: 0, explanation: 'This pattern, seen in humans and Drosophila among others, is called the XY type of sex determination.', difficulty: 'easy' },
  { id: 'piv-83', type: 'mcq', question: 'In grasshoppers, sex determination follows a pattern in which females have two X chromosomes (XX), while males have only a single X chromosome and no corresponding Y chromosome; this pattern is called:', options: ['XY type', 'ZW type', 'XO type', 'Haplodiploidy'], correctIndex: 2, explanation: 'The XO type of sex determination, seen in grasshoppers, involves females with XX and males with a single X chromosome (XO), lacking a Y.', difficulty: 'medium' },
  { id: 'piv-84', type: 'mcq', question: 'In the ZW type of sex determination, seen in birds, the female is typically:', options: ['Homogametic (ZZ)', 'Heterogametic (ZW)', 'The same as the male (both ZZ)', 'Determined entirely by environmental temperature'], correctIndex: 1, explanation: 'In the ZW system (seen in birds), the female is the heterogametic sex (ZW), while the male is homogametic (ZZ) — the reverse of the mammalian XY system.', difficulty: 'medium' },
  { id: 'piv-85', type: 'mcq', question: 'In the ZW type of sex determination, the male sex is characterised by which chromosome constitution?', options: ['ZW', 'ZZ (homogametic)', 'XY', 'XO'], correctIndex: 1, explanation: 'In the ZW system, males are homogametic with a ZZ constitution, while females are heterogametic (ZW).', difficulty: 'medium' },
  { id: 'piv-86', type: 'mcq', question: 'In honeybees, sex determination does not depend on sex chromosomes at all, but on chromosome number itself; this mechanism is called:', options: ['XY type', 'ZW type', 'Haplodiploidy', 'XO type'], correctIndex: 2, explanation: 'Haplodiploidy, seen in honeybees, is a sex-determination system where males develop from unfertilised (haploid) eggs, and females develop from fertilised (diploid) eggs.', difficulty: 'medium' },
  { id: 'piv-87', type: 'mcq', question: 'In the haplodiploid system of honeybees, male bees (drones) develop from:', options: ['Fertilised eggs, and are diploid', 'Unfertilised eggs, and are haploid', 'Fertilised eggs, but are haploid', 'The same eggs as female bees, with no distinction'], correctIndex: 1, explanation: 'In honeybees, males (drones) develop from unfertilised eggs and are haploid, whereas females develop from fertilised eggs and are diploid.', difficulty: 'medium' },
  { id: 'piv-88', type: 'mcq', question: 'In the haplodiploid sex-determination system, since males are haploid, they:', options: ['Produce sperm through meiosis, exactly as in diploid organisms', 'Do not undergo meiosis to produce sperm, since they have only one set of chromosomes', 'Are always sterile and cannot reproduce', 'Have the same chromosome number as female bees'], correctIndex: 1, explanation: 'Since haploid male bees have only one set of chromosomes, they do not undergo a typical meiotic reduction division to produce sperm.', difficulty: 'hard' },
  { id: 'piv-89', type: 'assertion', question: 'Assertion (A): In humans, roughly equal numbers of male and female offspring are produced in a large population.\nReason (R): Since sperm carrying an X chromosome and sperm carrying a Y chromosome are produced by the father in roughly equal numbers, and fertilisation is largely a matter of chance, the sex ratio at birth tends towards 1:1.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The equal production of X-bearing and Y-bearing sperm, combined with random fertilisation, correctly explains the near 1:1 sex ratio typically observed.', difficulty: 'medium' },
  { id: 'piv-90', type: 'assertion', question: 'Assertion (A): The pattern of sex determination differs among various animal groups.\nReason (R): While mammals typically use the XY system, birds use the ZW system, and some insects like grasshoppers use the XO system, reflecting evolutionary diversity in sex-determination mechanisms.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The existence of multiple distinct sex-determination systems across animal groups correctly explains and supports the assertion about differing patterns.', difficulty: 'medium' },
  { id: 'piv-91', type: 'count', question: 'Consider the following statements about sex determination:\n1. In humans, males are the heterogametic sex (XY).\n2. In birds, females are the heterogametic sex (ZW).\n3. In grasshoppers, males have an XX constitution while females have XO.\n4. In honeybees, males are haploid, developing from unfertilised eggs.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 4 are correct. Statement 3 is reversed — in grasshoppers, females have XX, and males have the single X (XO), not the other way around.', difficulty: 'medium' },
  { id: 'piv-92', type: 'count', question: 'Consider the following organisms:\n1. Humans\n2. Drosophila\n3. Birds\n4. Grasshoppers\n5. Honeybees\nHow many of the above organisms follow the XY type of sex determination (with males as XY)?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 1, explanation: 'Humans and Drosophila follow the XY system. Birds follow ZW, grasshoppers follow XO, and honeybees follow haplodiploidy.', difficulty: 'medium' },
  { id: 'piv-93', type: 'matching', question: 'Match Column I (organism) with Column II (sex-determination system):\nColumn I: A. Humans  B. Birds  C. Grasshoppers  D. Honeybees\nColumn II: i. Haplodiploidy  ii. XO type  iii. XY type  iv. ZW type', options: ['A-iii, B-iv, C-ii, D-i', 'A-i, B-ii, C-iii, D-iv', 'A-iv, B-iii, C-i, D-ii', 'A-iii, B-ii, C-iv, D-i'], correctIndex: 0, explanation: 'Humans — XY type; Birds — ZW type; Grasshoppers — XO type; Honeybees — haplodiploidy.', difficulty: 'medium' },
  { id: 'piv-94', type: 'statement', question: 'Statement I: In the ZW system, sex is determined by the type of gamete produced by the female parent.\nStatement II: This is because the female is the heterogametic sex in this system, producing two types of gametes (Z-bearing and W-bearing), while the male produces only one type (Z-bearing).\nIn light of the above statements, choose the most appropriate answer:', options: ['Both Statement I and Statement II are correct, and Statement II correctly explains Statement I', 'Both statements are correct, but Statement II does not explain Statement I', 'Statement I is correct, Statement II is incorrect', 'Statement I is incorrect, Statement II is correct'], correctIndex: 0, explanation: 'Since the female is heterogametic (ZW) in this system, her gamete type determines the offspring\'s sex, correctly explaining Statement I via Statement II.', difficulty: 'hard' },

  // ============ MUTATIONS ============
  { id: 'piv-95', type: 'mcq', question: 'A sudden, heritable change in the sequence of DNA (genetic material) of an organism is called a:', options: ['Recombination', 'Mutation', 'Linkage', 'Crossing over'], correctIndex: 1, explanation: 'A mutation is a sudden, heritable change in the DNA sequence, which can range from a change in a single base pair to a change in whole chromosomes.', difficulty: 'easy' },
  { id: 'piv-96', type: 'mcq', question: 'A mutation caused by a change involving only a single base pair of DNA is called a:', options: ['Point mutation', 'Chromosomal mutation', 'Frameshift mutation only', 'Aneuploidy'], correctIndex: 0, explanation: 'A point mutation is a change involving only a single base pair in the DNA sequence.', difficulty: 'easy' },
  { id: 'piv-97', type: 'mcq', question: 'Sickle cell anaemia, a well-studied genetic disorder in humans, is caused by:', options: ['A chromosomal mutation involving an entire chromosome', 'A point mutation in the beta-globin gene', 'A change in chromosome number', 'A deletion of an entire gene'], correctIndex: 1, explanation: 'Sickle cell anaemia is caused by a point mutation in the gene coding for the beta chain of haemoglobin, resulting in glutamic acid being replaced by valine.', difficulty: 'medium' },
  { id: 'piv-98', type: 'mcq', question: 'Changes in the number or structure of whole chromosomes, rather than in individual genes, are called:', options: ['Point mutations', 'Chromosomal mutations/aberrations', 'Gene conversions', 'Epigenetic modifications'], correctIndex: 1, explanation: 'Chromosomal mutations (aberrations) involve changes in the number or structural arrangement of chromosomes.', difficulty: 'medium' },
  { id: 'piv-99', type: 'mcq', question: 'A change in the number of one or a few chromosomes, rather than an entire set, is termed:', options: ['Aneuploidy', 'Euploidy', 'Polyploidy', 'Monosomy of all chromosomes'], correctIndex: 0, explanation: 'Aneuploidy refers to a gain or loss involving individual chromosomes, resulting from non-disjunction during cell division.', difficulty: 'medium' },
  { id: 'piv-100', type: 'mcq', question: 'A change in which an entire set (or sets) of chromosomes is added, resulting in an organism having more than the normal diploid number of chromosome sets, is called:', options: ['Aneuploidy', 'Polyploidy', 'Point mutation', 'Non-disjunction alone'], correctIndex: 1, explanation: 'Polyploidy refers to an increase in the whole set(s) of chromosomes, often seen in many plant species.', difficulty: 'medium' },
  { id: 'piv-101', type: 'mcq', question: 'Aneuploidy arises due to the failure of chromosomes to separate properly during cell division, a phenomenon called:', options: ['Crossing over', 'Non-disjunction', 'Independent assortment', 'Recombination'], correctIndex: 1, explanation: 'Non-disjunction, the failure of paired chromosomes to separate during meiosis (or mitosis), leads to aneuploidy — a gain or loss of individual chromosomes.', difficulty: 'medium' },
  { id: 'piv-102', type: 'assertion', question: 'Assertion (A): Point mutations, though involving only a single base pair, can have significant phenotypic consequences.\nReason (R): A single base change can alter the amino acid sequence of a protein, potentially affecting its structure and function, as seen in sickle cell anaemia.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The example of sickle cell anaemia correctly illustrates and explains how a single base pair change can have major phenotypic effects.', difficulty: 'medium' },
  { id: 'piv-103', type: 'assertion', question: 'Assertion (A): Aneuploidy typically arises due to errors during cell division.\nReason (R): Non-disjunction, the failure of homologous chromosomes or sister chromatids to separate properly, leads to gametes with an abnormal chromosome number, causing aneuploidy upon fertilisation.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'Non-disjunction during meiosis correctly explains the mechanistic origin of aneuploidy, matching the assertion.', difficulty: 'medium' },
  { id: 'piv-104', type: 'count', question: 'Consider the following statements about mutations:\n1. A point mutation involves a change in a single base pair of DNA.\n2. Sickle cell anaemia results from a chromosomal mutation, not a point mutation.\n3. Aneuploidy refers to a change in the number of individual chromosomes.\n4. Polyploidy refers to an increase in an entire chromosome set.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 3 and 4 are correct. Statement 2 is wrong — sickle cell anaemia results from a point mutation, not a chromosomal mutation.', difficulty: 'medium' },

  // ============ MENDELIAN (SINGLE GENE) DISORDERS IN HUMANS ============
  { id: 'piv-105', type: 'mcq', question: 'Genetic disorders caused by an alteration or mutation in a single gene are called:', options: ['Mendelian disorders', 'Chromosomal disorders', 'Multifactorial disorders only', 'Epigenetic disorders'], correctIndex: 0, explanation: 'Mendelian disorders are caused by alterations or mutations in a single gene, and their inheritance follows Mendelian principles.', difficulty: 'easy' },
  { id: 'piv-106', type: 'mcq', question: 'The pattern of inheritance of Mendelian disorders in a family can be traced using a chart of family history called a:', options: ['Karyogram', 'Pedigree chart', 'Punnett square only', 'Genome map'], correctIndex: 1, explanation: 'A pedigree analysis (pedigree chart) is used to trace a particular trait or disease through several generations of a family.', difficulty: 'medium' },
  { id: 'piv-107', type: 'mcq', question: 'Haemophilia, a Mendelian genetic disorder characterised by delayed blood clotting, is inherited in which pattern?', options: ['Autosomal dominant', 'Autosomal recessive', 'X-linked recessive', 'Y-linked'], correctIndex: 2, explanation: 'Haemophilia is an X-linked recessive disorder, meaning the gene is located on the X chromosome and the affected phenotype requires the recessive allele.', difficulty: 'medium' },
  { id: 'piv-108', type: 'mcq', question: 'Since haemophilia is X-linked recessive, a heterozygous (carrier) female is typically:', options: ['Affected by the disease, showing full symptoms', 'Unaffected, but capable of transmitting the disorder to offspring', 'Never able to have affected sons', 'Always sterile'], correctIndex: 1, explanation: 'A heterozygous female carrier does not show symptoms of haemophilia but can pass the recessive allele to her offspring.', difficulty: 'medium' },
  { id: 'piv-109', type: 'mcq', question: 'For a male to be affected by an X-linked recessive disorder such as haemophilia, he needs to inherit the mutant allele on:', options: ['Both of his X chromosomes', 'His single X chromosome, since he has only one', 'His Y chromosome', 'Any of his autosomes'], correctIndex: 1, explanation: 'Since males are hemizygous for X-linked genes (having only one X chromosome), a single copy of the mutant allele is sufficient to cause the disorder.', difficulty: 'medium' },
  { id: 'piv-110', type: 'mcq', question: 'Colour blindness, another well-known X-linked recessive disorder in humans, primarily affects the individual\'s ability to:', options: ['Distinguish between red and green colours', 'Hear specific frequency sounds', 'Digest lactose', 'Form blood clots'], correctIndex: 0, explanation: 'Colour blindness, an X-linked recessive condition, mainly impairs the ability to distinguish red and green colours.', difficulty: 'easy' },
  { id: 'piv-111', type: 'mcq', question: 'Sickle cell anaemia, an autosomal recessive Mendelian disorder in humans, is characterised by which structural change in the haemoglobin molecule?', options: ['Substitution of glutamic acid by valine at the sixth position of the beta-globin chain', 'Complete absence of the beta-globin chain', 'Duplication of the alpha-globin gene', 'Addition of an extra chromosome to chromosome 11'], correctIndex: 0, explanation: 'Sickle cell anaemia is caused by the substitution of glutamic acid by valine at the sixth position of the beta-globin chain of haemoglobin, due to a single base pair change (GAG to GUG) in the gene.', difficulty: 'hard' },
  { id: 'piv-112', type: 'mcq', question: 'In sickle cell anaemia, the mutant haemoglobin (HbS) causes red blood cells to:', options: ['Become round and enlarged', 'Polymerise and distort into a sickle shape, especially under low oxygen conditions', 'Completely lose their nucleus', 'Increase permanently in number'], correctIndex: 1, explanation: 'Under low oxygen tension, HbS molecules polymerise, causing the red blood cells to become elongated and sickle-shaped.', difficulty: 'medium' },
  { id: 'piv-113', type: 'mcq', question: 'The disorder is called sickle cell "anaemia" because the sickle-shaped red blood cells:', options: ['Have an increased capacity to carry oxygen', 'Are more fragile and hence prone to haemolysis, along with other complications, leading to a lowered red blood cell count', 'Cause an increase in overall red blood cell count', 'Never cause any impact on oxygen delivery'], correctIndex: 1, explanation: 'The sickle-shaped, fragile red blood cells undergo increased destruction (haemolysis), resulting in a reduced count and impaired oxygen-carrying capacity — hence the term "anaemia".', difficulty: 'medium' },
  { id: 'piv-114', type: 'mcq', question: 'The pattern of inheritance for sickle cell anaemia is:', options: ['Autosomal dominant', 'Autosomal recessive', 'X-linked dominant', 'Y-linked'], correctIndex: 1, explanation: 'Sickle cell anaemia follows an autosomal recessive pattern of inheritance; heterozygotes are generally unaffected carriers, while homozygous recessive individuals show the disease phenotype.', difficulty: 'medium' },
  { id: 'piv-115', type: 'mcq', question: 'Phenylketonuria, another autosomal recessive Mendelian disorder in humans, results from the deficiency of an enzyme that normally metabolises:', options: ['Phenylalanine', 'Glucose', 'Haemoglobin', 'Cholesterol'], correctIndex: 0, explanation: 'Phenylketonuria arises due to a deficiency of the enzyme phenylalanine hydroxylase, which normally converts phenylalanine into tyrosine.', difficulty: 'medium' },
  { id: 'piv-116', type: 'mcq', question: 'If left untreated, phenylketonuria leads to the accumulation of phenylalanine and its derivatives, causing which of the following consequences?', options: ['Mental retardation, among other symptoms', 'Complete blindness immediately after birth', 'Deafness alone, with no other symptoms', 'Complete infertility'], correctIndex: 0, explanation: 'The accumulation of phenylalanine and its harmful derivatives in individuals with phenylketonuria can cause mental retardation and other symptoms if untreated.', difficulty: 'medium' },
  { id: 'piv-117', type: 'mcq', question: 'Thalassemia, another Mendelian genetic disorder, is caused by:', options: ['A quantitative reduction in the synthesis of one or more globin chains of haemoglobin', 'A structural change resulting in glutamic acid being replaced by valine', 'A gain of an extra sex chromosome', 'An extra copy of an entire autosome'], correctIndex: 0, explanation: 'Thalassemia results from reduced synthesis (a quantitative problem) of one or more globin chains of haemoglobin, unlike sickle cell anaemia, which is a qualitative (structural) defect.', difficulty: 'hard' },
  { id: 'piv-118', type: 'assertion', question: 'Assertion (A): Sickle cell anaemia and thalassemia are both associated with haemoglobin, yet they are distinct disorders.\nReason (R): Sickle cell anaemia results from a qualitative defect (an abnormal haemoglobin structure), while thalassemia arises from a quantitative defect (reduced synthesis of normal globin chains).', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The distinction between structural (qualitative) versus reduced-synthesis (quantitative) haemoglobin defects correctly explains why the two disorders, though both haemoglobin-related, are distinct.', difficulty: 'hard' },
  { id: 'piv-119', type: 'assertion', question: 'Assertion (A): Haemophilia is more commonly observed in males than in females.\nReason (R): Since haemophilia is X-linked recessive and males have only one X chromosome, a single copy of the mutant allele is sufficient to cause the disease in males, whereas females generally require two copies.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The hemizygous condition of males for X-linked genes correctly explains why haemophilia is more common in males than in females.', difficulty: 'medium' },
  { id: 'piv-120', type: 'count', question: 'Consider the following statements about Mendelian disorders:\n1. Haemophilia is inherited as an X-linked recessive trait.\n2. Sickle cell anaemia is caused by a point mutation in the beta-globin gene.\n3. Phenylketonuria results from a deficiency of an enzyme that metabolises phenylalanine.\n4. Thalassemia is caused by an abnormal amino acid substitution in haemoglobin, similar to sickle cell anaemia.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 3 are correct. Statement 4 is wrong — thalassemia is caused by reduced synthesis of globin chains, not an amino acid substitution (that describes sickle cell anaemia).', difficulty: 'hard' },
  { id: 'piv-121', type: 'count', question: 'Consider the following disorders:\n1. Haemophilia\n2. Colour blindness\n3. Sickle cell anaemia\n4. Phenylketonuria\n5. Thalassemia\nHow many of the above are inherited in an X-linked recessive pattern?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 1, explanation: 'Haemophilia and colour blindness are X-linked recessive disorders. Sickle cell anaemia, phenylketonuria and thalassemia are autosomal recessive disorders.', difficulty: 'medium' },
  { id: 'piv-122', type: 'statement', question: 'Statement I: A phenotypically normal woman can still be a carrier of an X-linked recessive disorder like haemophilia.\nStatement II: Such a carrier female always shows some mild symptoms of the disorder, even though she is heterozygous.\nIn light of the above statements, choose the most appropriate answer:', options: ['Both Statement I and Statement II are correct', 'Both Statement I and Statement II are incorrect', 'Statement I is correct but Statement II is incorrect', 'Statement I is incorrect but Statement II is correct'], correctIndex: 2, explanation: 'Statement I is correct. Statement II is incorrect — a heterozygous carrier female is typically asymptomatic (unaffected) since the disorder is recessive.', difficulty: 'medium' },
  { id: 'piv-123', type: 'matching', question: 'Match Column I (Mendelian disorder) with Column II (inheritance pattern):\nColumn I: A. Haemophilia  B. Sickle cell anaemia  C. Phenylketonuria  D. Colour blindness\nColumn II: i. Autosomal recessive  ii. X-linked recessive  iii. Autosomal recessive  iv. X-linked recessive', options: ['A-ii, B-i, C-iii, D-iv', 'A-i, B-ii, C-iv, D-iii', 'A-iv, B-iii, C-ii, D-i', 'A-ii, B-iii, C-i, D-iv'], correctIndex: 0, explanation: 'Haemophilia — X-linked recessive; Sickle cell anaemia — autosomal recessive; Phenylketonuria — autosomal recessive; Colour blindness — X-linked recessive.', difficulty: 'medium' },

  // ============ CHROMOSOMAL DISORDERS IN HUMANS ============
  { id: 'piv-124', type: 'mcq', question: 'Chromosomal disorders in humans are caused by:', options: ['Mutation within a single gene only', 'Absence or excess of chromosomes, or abnormalities in the arrangement of genes within chromosomes', 'Environmental factors alone, with no genetic basis', 'Loss of a single base pair only'], correctIndex: 1, explanation: 'Chromosomal disorders arise from changes in chromosome number (absence or excess) or from structural abnormalities within chromosomes.', difficulty: 'medium' },
  { id: 'piv-125', type: 'mcq', question: 'Down syndrome, a well-known chromosomal disorder in humans, is caused by the presence of an extra copy of which chromosome?', options: ['Chromosome 13', 'Chromosome 18', 'Chromosome 21', 'The X chromosome'], correctIndex: 2, explanation: 'Down syndrome is caused by trisomy of chromosome 21, resulting in an individual having 47 chromosomes instead of the usual 46.', difficulty: 'easy' },
  { id: 'piv-126', type: 'mcq', question: 'Individuals with Down syndrome exhibit which of the following characteristic features?', options: ['Short stature, small round head, furrowed tongue, and partially open mouth', 'Extremely tall stature with very slender build', 'Complete absence of any cognitive or physical developmental differences', 'Only cardiovascular symptoms, with no other visible features'], correctIndex: 0, explanation: 'Down syndrome patients show characteristic features such as short stature, small round head, furrowed tongue, and partially open mouth, among others.', difficulty: 'medium' },
  { id: 'piv-127', type: 'mcq', question: 'Turner syndrome, another well-known chromosomal disorder in humans, results from the absence of one X chromosome, giving affected individuals a total of how many chromosomes?', options: ['44 chromosomes', '45 chromosomes (44 + X0)', '46 chromosomes', '47 chromosomes'], correctIndex: 1, explanation: 'Turner syndrome individuals have a chromosome number of 45, with a single X chromosome (44 autosomes + XO), instead of the usual 46 (44+XX).', difficulty: 'medium' },
  { id: 'piv-128', type: 'mcq', question: 'Individuals with Turner syndrome typically have which sex chromosome constitution?', options: ['XXY', 'XYY', 'XO', 'XXX'], correctIndex: 2, explanation: 'Turner syndrome results from monosomy of the X chromosome (45, XO), i.e., the absence of one X chromosome.', difficulty: 'medium' },
  { id: 'piv-129', type: 'mcq', question: 'Individuals with Turner syndrome are:', options: ['Genetically female but sterile, with underdeveloped ovaries', 'Genetically male but with female external features', 'Fertile females with no distinguishing features', 'Always intersex with ambiguous genitalia'], correctIndex: 0, explanation: 'Turner syndrome individuals are phenotypically female but sterile, with rudimentary ovaries and lacking secondary sexual characters.', difficulty: 'medium' },
  { id: 'piv-130', type: 'mcq', question: 'Klinefelter syndrome, another chromosomal disorder in humans, results from an additional copy of the X chromosome in a male, giving a genotype of:', options: ['46, XY', '47, XXY', '45, XO', '47, XYY'], correctIndex: 1, explanation: 'Klinefelter syndrome individuals have an overall chromosome number of 47, with an XXY sex chromosome constitution.', difficulty: 'medium' },
  { id: 'piv-131', type: 'mcq', question: 'Individuals with Klinefelter syndrome show phenotypic features including:', options: ['Overall masculine development, along with feminising features such as gynaecomastia (enlarged breasts)', 'Complete absence of any male features', 'Extremely short stature, resembling Turner syndrome', 'No effect on fertility whatsoever'], correctIndex: 0, explanation: 'Klinefelter syndrome individuals show overall masculine development, but with certain feminine characteristics such as the development of breasts (gynaecomastia).', difficulty: 'medium' },
  { id: 'piv-132', type: 'assertion', question: 'Assertion (A): Down syndrome and Turner syndrome are both chromosomal disorders, yet they differ fundamentally in their underlying chromosomal abnormality.\nReason (R): Down syndrome results from trisomy (an extra autosome, chromosome 21), while Turner syndrome results from monosomy of a sex chromosome (absence of one X).', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The contrast between autosomal trisomy (Down syndrome) and sex chromosome monosomy (Turner syndrome) correctly explains their fundamental difference, as described in the assertion.', difficulty: 'hard' },
  { id: 'piv-133', type: 'assertion', question: 'Assertion (A): Klinefelter syndrome individuals show both male and female characteristics.\nReason (R): The presence of an extra X chromosome, along with the Y chromosome, in Klinefelter syndrome (XXY) leads to overall masculine development along with some feminising features such as gynaecomastia.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The specific chromosomal composition (XXY) directly explains the mixed masculine/feminine phenotypic presentation described in the assertion.', difficulty: 'medium' },
  { id: 'piv-134', type: 'count', question: 'Consider the following statements about chromosomal disorders:\n1. Down syndrome is caused by trisomy of chromosome 21.\n2. Turner syndrome individuals have an XXY sex chromosome constitution.\n3. Klinefelter syndrome individuals are genetically male but show some feminising features.\n4. Down syndrome patients typically have 47 chromosomes instead of the usual 46.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 3 and 4 are correct. Statement 2 is wrong — Turner syndrome individuals have an XO constitution, not XXY (which describes Klinefelter syndrome).', difficulty: 'medium' },
  { id: 'piv-135', type: 'count', question: 'Consider the following syndromes:\n1. Down syndrome\n2. Turner syndrome\n3. Klinefelter syndrome\n4. Sickle cell anaemia\n5. Phenylketonuria\nHow many of the above are chromosomal disorders, rather than single-gene (Mendelian) disorders?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Down syndrome, Turner syndrome, and Klinefelter syndrome are chromosomal disorders. Sickle cell anaemia and phenylketonuria are Mendelian (single-gene) disorders.', difficulty: 'medium' },
  { id: 'piv-136', type: 'statement', question: 'Statement I: Chromosomal disorders generally arise due to errors during cell division, particularly non-disjunction of chromosomes.\nStatement II: All chromosomal disorders in humans are inherited from a parent and can never arise spontaneously in an individual.\nIn light of the above statements, choose the most appropriate answer:', options: ['Both Statement I and Statement II are correct', 'Both Statement I and Statement II are incorrect', 'Statement I is correct but Statement II is incorrect', 'Statement I is incorrect but Statement II is correct'], correctIndex: 2, explanation: 'Statement I is correct. Statement II is incorrect — chromosomal disorders can arise spontaneously due to errors (non-disjunction) during gamete formation, even if neither parent shows the disorder.', difficulty: 'medium' },
  { id: 'piv-137', type: 'matching', question: 'Match Column I (chromosomal disorder) with Column II (chromosomal basis):\nColumn I: A. Down syndrome  B. Turner syndrome  C. Klinefelter syndrome\nColumn II: i. 45, XO  ii. 47, XXY  iii. Trisomy of chromosome 21', options: ['A-iii, B-i, C-ii', 'A-i, B-ii, C-iii', 'A-ii, B-iii, C-i', 'A-iii, B-ii, C-i'], correctIndex: 0, explanation: 'Down syndrome — trisomy 21; Turner syndrome — 45, XO; Klinefelter syndrome — 47, XXY.', difficulty: 'medium' },

  // ============ MIXED / REVISION ============
  { id: 'piv-138', type: 'mcq', question: 'Which of the following best distinguishes a Mendelian disorder from a chromosomal disorder?', options: ['Mendelian disorders are caused by mutations in a single gene, whereas chromosomal disorders involve changes in chromosome number or structure', 'Mendelian disorders are always fatal, while chromosomal disorders are never fatal', 'Mendelian disorders affect only males, while chromosomal disorders affect only females', 'There is no meaningful difference between the two categories'], correctIndex: 0, explanation: 'The fundamental distinction lies in the scale of the genetic change: single-gene mutation (Mendelian) versus whole chromosome number/structure changes (chromosomal).', difficulty: 'medium' },
  { id: 'piv-139', type: 'mcq', question: 'Which of the following pairs is INCORRECTLY matched?', options: ['Sickle cell anaemia — autosomal recessive', 'Haemophilia — X-linked recessive', 'Down syndrome — single gene mutation', 'Klinefelter syndrome — XXY'], correctIndex: 2, explanation: 'Down syndrome is caused by trisomy of chromosome 21 (a chromosomal disorder), not by a single gene mutation.', difficulty: 'medium' },
  { id: 'piv-140', type: 'assertion', question: 'Assertion (A): Mendel\'s principles of inheritance, though formulated using garden pea, apply broadly across sexually reproducing organisms, including humans.\nReason (R): The fundamental cellular processes of meiosis, which underlie segregation and independent assortment of alleles, are conserved across most sexually reproducing eukaryotic species.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The conservation of meiotic mechanisms across sexually reproducing eukaryotes correctly explains why Mendel\'s principles, though derived from pea, apply broadly.', difficulty: 'medium' },
  { id: 'piv-141', type: 'count', question: 'Consider the following statements summarising the chapter:\n1. Mendel\'s Law of Dominance and Law of Segregation both apply to a single gene pair.\n2. The Law of Independent Assortment applies specifically to two or more gene pairs.\n3. All genetic disorders in humans are chromosomal in origin.\n4. Both point mutations and chromosomal aberrations can lead to genetic disorders in humans.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 4 are correct. Statement 3 is wrong — many genetic disorders (e.g., sickle cell anaemia, haemophilia) are Mendelian (single-gene), not chromosomal.', difficulty: 'medium' },
  { id: 'piv-142', type: 'count', question: 'Consider the following pairs:\n1. Incomplete dominance — Mirabilis jalapa\n2. Codominance — ABO blood group\n3. Multiple alleles — Phenylketonuria\n4. Pleiotropy — Sickle cell anaemia (multiple effects on the body)\nHow many of the above pairs are correctly matched?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Pairs 1, 2 and 4 are correctly matched. Pair 3 is incorrect — phenylketonuria is generally cited as an example of pleiotropy, not multiple alleles; the ABO blood group is the classic multiple allele example.', difficulty: 'hard' },
  { id: 'piv-143', type: 'statement', question: 'Statement I: Sex determination mechanisms are uniform across all animal species.\nStatement II: Different animal groups, such as mammals, birds, some insects, and honeybees, show distinct sex-determination systems (XY, ZW, XO, and haplodiploidy respectively).\nIn light of the above statements, choose the most appropriate answer:', options: ['Both Statement I and Statement II are correct', 'Both Statement I and Statement II are incorrect', 'Statement I is correct but Statement II is incorrect', 'Statement I is incorrect but Statement II is correct'], correctIndex: 3, explanation: 'Statement I is incorrect — sex-determination mechanisms vary widely across species. Statement II correctly describes this diversity.', difficulty: 'medium' },
  { id: 'piv-144', type: 'mcq', question: 'Which of the following statements correctly reflects the historical development of genetics as described in this chapter?', options: ['Mendel\'s principles were understood immediately upon publication in 1865 and quickly became the foundation of genetics', 'Mendel\'s work was largely overlooked until it was independently rediscovered around 1900, after which the chromosomal theory and later molecular studies (e.g., Morgan\'s Drosophila work) built upon his principles', 'The chromosomal theory of inheritance preceded and directly inspired Mendel\'s original experiments', 'Genetic disorders in humans were fully characterised before Mendel\'s principles were established'], correctIndex: 1, explanation: 'Mendel\'s work, published in 1865, was largely overlooked until its rediscovery around 1900, after which subsequent researchers (Sutton, Boveri, Morgan and others) built upon and validated his principles using chromosome studies.', difficulty: 'medium' },
  { id: 'piv-145', type: 'assertion', question: 'Assertion (A): Understanding the principles of inheritance and variation has significant applications beyond basic biology, including in medicine and agriculture.\nReason (R): Knowledge of inheritance patterns allows for genetic counselling regarding hereditary disorders and informs selective breeding strategies for desirable traits in crops and livestock.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The practical applications in genetic counselling and selective breeding correctly explain the broader significance of understanding inheritance principles, as stated in the assertion.', difficulty: 'medium' },
];